def transform(grid):
    out = [row[:] for row in grid]
    for i, row in enumerate(grid):
        if len(set(row)) == 1:
            out[i] = [2 if v == row[0] else v for v in row]
    for j in range(len(grid[0])):
        if len({row[j] for row in grid}) == 1:
            for i in range(len(grid)):
                out[i][j] = 2
    return out
